def read_count(text):
    count = int(text)
    if count < 0:
        raise ValueError("数量不能为负")
    return count

for text in ["3", "0", "-1", "三"]:
    try:
        print(read_count(text))
    except ValueError:
        print("请输入非负整数")

def count_passed(scores):
    passed = 0
    for score in scores:
        if score >= 60:
            passed = passed + 1
    return passed

assert count_passed([59, 60, 90]) == 2
assert count_passed([]) == 0
